-- Run after deploy to refresh trust pages (edit text in admin anytime).

UPDATE pages SET content = '<p>PromptsBox (promptsbox.com) is a free library of AI prompts, creator tools, and practical guides. We help you write better prompts for image AI, Instagram, TikTok, and everyday content work — without endless searching.</p><h2>What we offer</h2><ul><li>Copy-ready prompt collections by topic</li><li>Free generators: bios, captions, hashtags, meta tags, and more</li><li>Step-by-step articles written for real creators</li></ul><h2>Who we are</h2><p>PromptsBox is built and maintained by our editorial team. We focus on useful, original content that follows Google and AdSense quality guidelines.</p><p>Questions? Visit our <a href="/page/contact">Contact</a> page.</p>',
meta_title = 'About PromptsBox', meta_description = 'Learn about PromptsBox — free AI prompts, tools, and guides for creators.'
WHERE slug = 'about';

UPDATE pages SET content = '<p>We would love to hear from you. Use the form below for partnerships, corrections, or general questions.</p><p>We usually respond within 2–3 business days. For privacy requests, mention &quot;Privacy&quot; in the subject line.</p>',
meta_title = 'Contact PromptsBox', meta_description = 'Contact PromptsBox for support, feedback, and business inquiries.'
WHERE slug = 'contact';

UPDATE pages SET content = '<p><strong>Last updated:</strong> November 2026</p><p>PromptsBox (&quot;we&quot;, &quot;our&quot;, &quot;us&quot;) operates https://promptsbox.com. This Privacy Policy explains how we collect, use, and protect your information when you use our website.</p><h2>Information we collect</h2><ul><li><strong>Contact form:</strong> name, email, message, and technical data such as IP address for spam prevention.</li><li><strong>Usage data:</strong> pages visited, device type, and approximate location via analytics cookies (if you consent).</li><li><strong>Cookies:</strong> small files stored on your device to remember preferences and measure traffic.</li></ul><h2>How we use information</h2><ul><li>Operate and improve the website</li><li>Respond to contact messages</li><li>Measure audience with Google Analytics (when enabled and consented)</li><li>Display advertising through Google AdSense (when enabled and consented)</li></ul><h2>Google AdSense &amp; third parties</h2><p>Third-party vendors, including Google, use cookies to serve ads based on your visits to this and other websites. You may opt out of personalized advertising by visiting <a href="https://www.google.com/settings/ads" rel="nofollow noopener" target="_blank">Google Ads Settings</a>.</p><p>Google''s use of advertising cookies enables it and its partners to serve ads to you. See Google''s <a href="https://policies.google.com/technologies/ads" rel="nofollow noopener" target="_blank">advertising policy</a>.</p><h2>Your rights</h2><p>Depending on your region, you may request access, correction, or deletion of personal data. Contact us via the <a href="/page/contact">Contact</a> page.</p><h2>Children</h2><p>Our site is not directed at children under 16.</p><h2>Changes</h2><p>We may update this policy. The &quot;Last updated&quot; date will change when we do.</p>',
meta_title = 'Privacy Policy', meta_description = 'PromptsBox privacy policy — cookies, analytics, and advertising.'
WHERE slug = 'privacy-policy';

UPDATE pages SET content = '<p>By using PromptsBox you agree to these Terms of Service. If you disagree, please do not use the site.</p><h2>Use of the site</h2><ul><li>Content is for personal and commercial creator use unless stated otherwise.</li><li>Do not scrape, overload, or attempt to hack the service.</li><li>Tool outputs are suggestions; you are responsible for how you use them.</li></ul><h2>Intellectual property</h2><p>Site design, branding, and original articles are owned by PromptsBox. Do not republish full articles without permission.</p><h2>Limitation of liability</h2><p>The site is provided &quot;as is&quot; without warranties. We are not liable for indirect damages from use of prompts, tools, or third-party links.</p><h2>Governing law</h2><p>These terms are governed by applicable law in the jurisdiction of the site operator.</p>',
meta_title = 'Terms of Service', meta_description = 'PromptsBox terms of service.'
WHERE slug = 'terms-of-service';

UPDATE pages SET content = '<p>PromptsBox provides AI prompt examples and automated text suggestions. Outputs may be inaccurate or incomplete. Always review before publishing.</p><ul><li>We do not guarantee rankings, earnings, or AdSense approval.</li><li>We are not affiliated with Instagram, TikTok, Google, OpenAI, or Meta unless stated.</li><li>Trademarks belong to their respective owners.</li></ul>',
meta_title = 'Disclaimer', meta_description = 'PromptsBox disclaimer for AI tools and content.'
WHERE slug = 'disclaimer';